<template><view class="page"><nav-bar title="试卷预览" :showBack="true" placeholder rightText="答案" @right-click="showAnswer=!showAnswer"/><scroll-view scroll-y class="paper"><view class="header"><text class="title">{{paper.name}}</text><text>{{paper.subject}} · {{paper.category}}</text><text>{{paper.duration?paper.duration+'分钟 · ':''}}{{paper.questionCount||0}}题 · {{paper.totalScore||0}}分</text><text v-if="paper.remark" class="remark">{{paper.remark}}</text></view><view v-for="(item,index) in paper.questions" :key="item.id" class="question"><view class="q-title"><text>{{index+1}}. {{item.question.content}}</text><text>（{{item.score}}分）</text></view><view v-if="options(item.question.options)" class="options"><text v-for="(op,i) in options(item.question.options)" :key="i">{{String.fromCharCode(65+i)}}. {{op}}</text></view><view v-if="showAnswer" class="answer"><text>答案：{{item.question.answer||'暂无'}}</text><text>解析：{{item.question.analysis||'暂无'}}</text></view></view></scroll-view><view class="bottom"><button class="secondary" @click="save">保存草稿</button><button class="primary" :loading="saving" @click="complete">完成组卷</button></view></view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import{getPaper,completePaper}from'@/api/paper.js';export default{components:{NavBar},data(){return{paperId:null,paper:{questions:[]},showAnswer:false,saving:false}},onLoad(q){this.paperId=q.paperId;this.load()},methods:{async load(){const r=await getPaper(this.paperId);this.paper=r.data},options(v){if(!v)return[];try{return JSON.parse(v)}catch(e){return[]}},save(){uni.showToast({title:'草稿已保存',icon:'success'})},async complete(){if(!this.paper.questions?.length)return uni.showToast({title:'至少选择一道题',icon:'none'});if(this.paper.questions.some(x=>Number(x.score)<=0))return uni.showToast({title:'题目分值必须大于0',icon:'none'});this.saving=true;try{await completePaper(this.paperId);uni.showToast({title:'组卷完成',icon:'success'});setTimeout(()=>uni.redirectTo({url:'/subpackage_ai/paperMine/paperMine'}),700)}finally{this.saving=false}}}}</script>
<style scoped lang="scss">.page{min-height:100vh;background:#eef2f7;padding-bottom:120rpx}.paper{height:calc(100vh - 210rpx);background:#fff;margin:20rpx 24rpx;width:auto;padding:34rpx;box-sizing:border-box;border-radius:12rpx}.header{text-align:center;border-bottom:2rpx solid #d9dee7;padding-bottom:24rpx;color:#69758a}.header text{display:block;margin:8rpx}.title{font-size:36rpx!important;font-weight:700;color:#202d42}.remark{font-size:23rpx}.question{padding:26rpx 0;border-bottom:1rpx solid #edf0f5}.q-title{display:flex;justify-content:space-between;gap:20rpx;color:#26354c;font-size:27rpx;line-height:1.6}.options text,.answer text{display:block;font-size:25rpx;line-height:1.8;color:#566379}.options{margin:10rpx 0 0 30rpx}.answer{background:#f1f6ff;padding:16rpx;border-radius:12rpx;margin-top:14rpx;color:#3f65bb}.bottom{position:fixed;bottom:0;left:0;right:0;background:#fff;display:flex;gap:16rpx;padding:16rpx 24rpx calc(16rpx + env(safe-area-inset-bottom))}.bottom button{flex:1;border-radius:40rpx;font-size:26rpx}.secondary{background:#edf2fc;color:#4d78e8}.primary{background:#4d78e8;color:#fff}</style>
